/bin/bash -lc "cat <<'EOF' > /vercel/sandbox/app/components/ThemePreference.tsx
import { cookies, headers } from 'next/headers';

function parsePreferredLanguage(acceptLanguage: string | null): string {
  if ("'!acceptLanguage) {
    return '"'unknown';
  }

  const primary = acceptLanguage.split(',')[0];
  return primary?.trim() || 'unknown';
}

export default async function ThemePreference() {
  const cookieStore = await cookies();
  const headerStore = await headers();

  const theme = cookieStore.get('theme')?.value ?? 'light';
  const preferredLanguage = parsePreferredLanguage(
    headerStore.get('accept-language')
  );

  return (
    <section>
      <h2>Current Preferences</h2>
      <p>
        Theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{preferredLanguage}</strong>
      </p>
    </section>
  );
}
EOF"

